insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"OPEN_QUIET_LOSER","title":"¿Habrá ventaja de 3 o más y el perdedor en 2 o menos?","description":"Se corrige con el marcador final.","category":"abierto","difficulty":"medium","points":4,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"and","rules":[{"op":"margin_gte","n":3},{"op":"loser_lte","n":2}]},"priority":0,"cooldown":2,"tags":["abierto"]},{"code":"SHUTOUT_FIVE","title":"¿Habrá blanqueada y el ganador anota 5 o más?","description":"Se corrige con el marcador final.","category":"defensiva","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"and","rules":[{"op":"shutout"},{"op":"winner_gte","n":5}]},"priority":0,"cooldown":2,"tags":["defensiva"]},{"code":"OFFENSE_BOTH4_CLOSE","title":"¿Ambos llegan a 4 y el partido no se abre a más de 2?","description":"Se corrige con el marcador final.","category":"ofensiva","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"and","rules":[{"op":"both_gte","n":4},{"op":"margin_lte","n":2}]},"priority":0,"cooldown":2,"tags":["ofensiva"]},{"code":"LOW_AND_CLOSE","title":"¿Habrá 6 o menos carreras y diferencia de 2 o menos?","description":"Se corrige con el marcador final.","category":"defensiva","difficulty":"hard","points":6,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"and","rules":[{"op":"total_lte","n":6},{"op":"margin_lte","n":2}]},"priority":0,"cooldown":2,"tags":["defensiva"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;